def design(feats):
    X = np.asarray(feats.x, float)
    y = np.asarray(feats.y, float)
    n, p = X.shape
    ids = list(feats.ids)
    labs = sorted(set(feats.stratum))
    S = np.array([[1.0 if s == l else 0.0 for l in labs[1:]] for s in feats.stratum]).reshape(n, -1)

    def loglik(Z):
        A = np.column_stack([np.ones(n), S] + ([Z] if Z is not None and Z.size else []))
        b = np.zeros(A.shape[1])
        for _ in range(50):
            mu = 1 / (1 + np.exp(-np.clip(A @ b, -30, 30)))
            w = mu * (1 - mu) + 1e-9
            H = A.T @ (A * w[:, None]) + 1e-4 * np.eye(A.shape[1])
            step = np.linalg.solve(H, A.T @ (y - mu) - 1e-4 * b)
            b += step
            if np.max(np.abs(step)) < 1e-8:
                break
        mu = np.clip(1 / (1 + np.exp(-np.clip(A @ b, -30, 30))), 1e-12, 1 - 1e-12)
        return float(np.sum(y * np.log(mu) + (1 - y) * np.log(1 - mu)))

    C = np.corrcoef(X, rowvar=False)
    a_first, a_next = 0.15 / p, 0.05 / p
    sel = []
    base = loglik(None)
    while len(sel) < MAX_DRIVERS:
        best, bp, bl = None, 1.0, None
        for j in range(p):
            if j in sel or any(abs(C[j, k]) >= 0.6 for k in sel):
                continue
            ll = loglik(X[:, sel + [j]])
            pv = stats.chi2.sf(2 * (ll - base), 1)
            if pv < bp:
                best, bp, bl = j, pv, ll
        if best is None or bp > (a_first if not sel else a_next / (5 if len(sel) > 1 else 1)):
            break
        sel.append(best)
        base = bl
    if len(sel) > 1:
        full = loglik(X[:, sel])
        keep = []
        for j in sel:
            rest = [k for k in sel if k != j]
            if stats.chi2.sf(2 * (full - loglik(X[:, rest])), 1) < a_next:
                keep.append(j)
        sel = keep if keep else sel[:1]
    prods = []
    cands = []
    for a in range(p):
        for b in range(a, p):
            if a != b and abs(C[a, b]) >= 0.6:
                continue
            mains = sel + [k for k in {a, b} if k not in sel]
            lm = loglik(X[:, mains])
            pv = stats.chi2.sf(2 * (loglik(np.column_stack([X[:, mains], X[:, a] * X[:, b]])) - lm), 1)
            if pv < 0.002 / (p * (p + 1) / 2):
                cands.append((pv, a, b))
    for pv, a, b in sorted(cands)[:2]:
        if len(sel) + len({a, b} - set(sel)) > MAX_DRIVERS:
            continue
        sel += [k for k in dict.fromkeys((a, b)) if k not in sel]
        prods.append((ids[a], ids[b]))
    drivers = tuple(ids[j] for j in sel)
    return Design(drivers=drivers, columns=drivers, products=tuple(prods), loadings={})

